const sha = (v: unknown) =>
  createHash("sha256").update(JSON.stringify(v)).digest("hex").slice(0, 20);

/** Timings vary run to run; everything else must not. */
function stable(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(stable);
  if (v && typeof v === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, x] of Object.entries(v as Record<string, unknown>)) {
      if (/Ms$|^ms$|At$|^timing$|elapsed|latency|duration/.test(k)) continue;
      out[k] = stable(x);
    }
    return out;
  }
  return v;
}

// ── The stored compact context, over every real fixture ──────────────

type Pos = { lines?: Record<string, unknown>[]; bestMove?: string };

function adversarial(ge: { positions: Pos[] }) {
  const clone = () => JSON.parse(JSON.stringify(ge)) as { positions: Pos[] };
  const edit = (f: (p: Pos[]) => void) => {
    const c = clone();
    f(c.positions);
    return c;
  };
  const mid = Math.floor(ge.positions.length / 2);
  return {
    nullCp: edit((p) => {
      if (p[mid]?.lines?.[0]) p[mid].lines![0].cp = null;
    }),
    mates: edit((p) => {
      if (p[mid]?.lines?.[0]) p[mid].lines![0] = { mate: 3, depth: 16, pv: [] };
      if (p[mid + 1]?.lines?.[0])
        p[mid + 1].lines![0] = { mate: -2, depth: 16, pv: [] };
    }),
    sentinel: edit((p) => {
      if (p[mid]?.lines?.[0]) p[mid].lines![0].depth = 0;
    }),
    depthMismatch: (() => {
      const c = edit((p) => {
        if (p[mid]?.lines?.[0]) p[mid].lines![0].depth = 8;
      });
      return { ...c, settings: { depth: 16 } };
    })(),
    garbageBest: edit((p) => {
      if (p[mid]) p[mid].bestMove = "z9z9";
      if (p[mid + 1]) p[mid + 1].bestMove = "N/A";
    }),
  };
}

function compactCases(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const f of fs.readdirSync(REAL).filter((f) => f.endsWith(".json"))) {
    const fx = JSON.parse(fs.readFileSync(path.join(REAL, f), "utf8"));
    for (const colour of ["w", "b", "white", "black", ""])
      out[`${f}:${colour}`] = buildCompactGameContext(
        fx.moveHistory,
        fx.gameEval,
        colour
      );
    out[`${f}:noeval`] = buildCompactGameContext(
      fx.moveHistory,
      undefined,
      "w"
    );
    for (const [name, ge] of Object.entries(adversarial(fx.gameEval)))
      for (const colour of ["w", "b"])
        out[`${f}:${name}:${colour}`] = buildCompactGameContext(
          fx.moveHistory,
          ge as never,
          colour
        );
    const broken = [...fx.moveHistory];
    broken[Math.floor(broken.length / 2)] = "Qxz9";
    out[`${f}:illegal`] = buildCompactGameContext(broken, fx.gameEval, "w");
  }
  return out;
}

// ── The route, over fixture 07 with its real stored context ──────────

const FX = JSON.parse(
  fs.readFileSync(path.join(REAL, "07_knight_fork.json"), "utf8")
);
const MOVES: string[] = FX.moveHistory;
const fenAfter = (n: number) => {
  const g = new Chess();
  for (const m of MOVES.slice(0, n)) g.move(m);
  return g.fen();
};

interface Turn {
  name: string;
  body: Record<string, unknown>;
  /** Names a side, an owner or a mis-dotted move: may differ with the flag on. */
  sided?: boolean;
  /** The coach's draft for this turn, when not the shared one. */
  draft?: string;
}

