const llm = (content: string) => ({
  content,
  inputTokens: 1,
  outputTokens: 1,
  model: "claude-haiku-4-5",
  provider: "anthropic",
});
const DRAFT =
  "8. Nc7+ forks the king and rook, but 8. Qxc1 wins the queen outright. Lesson: before a fork, take what is hanging.";

let calls: Record<string, unknown>[] = [];
let draft = DRAFT;
async function serve(turn: Turn) {
  calls = [];
  draft = turn.draft ?? DRAFT;
  const res = await POST(
    new NextRequest("http://x/api/chat", {
      method: "POST",
      body: JSON.stringify({
        contextId: "golden",
        moveIndex: MOVES.length,
        ...turn.body,
      }),
      headers: { "Content-Type": "application/json" },
    })
  );
  const json = await res.json();
  return sha({
    status: res.status,
    calls: calls.map((c) => ({
      system: c.system,
      systemSuffix: c.systemSuffix,
      messages: c.messages,
    })),
    response: stable(json),
  });
}

const MODES = [
  { name: "validators-on", validators: "true", prompt: "" },
  { name: "validators-off", validators: "false", prompt: "" },
  { name: "legacy", validators: "false", prompt: "legacy" },
];

describe("byte for byte as at 5d592e7", () => {
  beforeEach(async () => {
    vi.clearAllMocks();
    vi.stubEnv("COACH_WHATIF_EVALS", "1");
    mockSession.mockResolvedValue({ session: { uid: "u" } });
    mockClassifyQuestion.mockResolvedValue({
      category: "position_analysis",
      confidence: 0.9,
      rationale: "t",
    });
    mockFetchDataSources.mockResolvedValue({
      featureDelta: undefined,
      pieceRoleDiff: [],
      scout: undefined,
      userHistory: undefined,
    });
    mockCallLLM.mockImplementation(async (opts: Record<string, unknown>) => {
      if (opts.outputSchema || /claims/i.test(String(opts.system ?? "")))
        return llm('{"claims":[]}');
      calls.push(opts);
      return llm(draft);
    });
    const contract = await buildCoachContract({
      moveHistory: MOVES,
      gameEval: FX.gameEval,
      playerColor: "w",
      username: FX.username,
      userRating: FX.userRating,
      gameHeaders: FX.gameHeaders,
      identity: { fen: fenAfter(MOVES.length), playerColor: "w" },
    });
    const served = selectCardInsights(contract).map((i) => i.factIdPrefix);
    const parts = getCoachChatSystemPromptParts({
      personalityId: "friendly",
      userRating: FX.userRating,
      username: FX.username,
      playerColorName: "white",
    });
    const stored = {
      contextId: "golden",
      gameContext: "",
      compactGameContext: buildCompactGameContext(MOVES, FX.gameEval, "w"),
      playedMoves: MOVES,
      systemPrompt: `${parts.stable}\n\n${parts.perUser}`,
      systemPromptStable: parts.stable,
      systemPromptSuffix: parts.perUser,
      fewShotExamples: "",
      fen: fenAfter(MOVES.length),
      skillLevel: "intermediate",
      playerColor: "w",
      moveCount: 10,
      createdAt: 0,
      initialAnalysis: "Your review.",
      gameEval: FX.gameEval,
      compactContract: toCompactContract(contract, served),
    };
    mockGetAnalysisContext.mockImplementation(() =>
      JSON.parse(JSON.stringify(stored))
    );
  });

  afterEach(() => {
    vi.unstubAllEnvs();
    __resetMastermindEnvCacheForTests();
  });

  async function routeHashes(flag: string) {
    const out: Record<string, string> = {};
    for (const mode of MODES) {
      vi.stubEnv("MASTERMIND_VALIDATORS_ENABLED", mode.validators);
      vi.stubEnv("COACH_FOLLOWUP_PROMPT", mode.prompt);
      vi.stubEnv("COACH_PERSPECTIVE", flag);
      __resetMastermindEnvCacheForTests();
      for (const turn of TURNS)
        if (flag === "" || !turn.sided)
          out[`${mode.name}:${turn.name}`] = await serve(turn);
    }
    return out;
  }

  it("the stored compact context and the route's inputs and response", async () => {
    const compact = Object.fromEntries(
      Object.entries(compactCases()).map(([k, v]) => [k, sha(v)])
    );
    const route = await routeHashes("");
    if (process.env.GOLDEN_WRITE) {
      fs.writeFileSync(
        process.env.GOLDEN_WRITE,
        JSON.stringify({ compact, route }, null, 1) + "\n"
      );
      return;
    }
    const golden = JSON.parse(fs.readFileSync(GOLDEN, "utf8"));
    expect(compact).toEqual(golden.compact);
    // Flag off: every turn, a side named in the words or the field
    // included.
    expect(route).toEqual(golden.route);
    // Flag on: every turn that names no side, owner or mis-dotted move.
    const on = await routeHashes("1");
    for (const [k, v] of Object.entries(on)) expect(v, k).toBe(golden.route[k]);
    expect(Object.keys(on).length).toBe(
      MODES.length * TURNS.filter((t) => !t.sided).length
    );
  }, 120_000);

  // Pathway 3.1: under COACH_FOLLOWUP_PROMPT=fielded, every turn the plan
  // does not field (no anchor, a walkthrough, no contract) is the v1 turn,
  // byte for byte.
  it("a turn the fielded mode does not field is the v1 turn, byte for byte", async () => {
    const golden = JSON.parse(fs.readFileSync(GOLDEN, "utf8"));
    for (const mode of MODES.filter((m) => m.prompt === "")) {
      vi.stubEnv("MASTERMIND_VALIDATORS_ENABLED", mode.validators);
      vi.stubEnv("COACH_FOLLOWUP_PROMPT", "fielded");
      vi.stubEnv("COACH_PERSPECTIVE", "");
      __resetMastermindEnvCacheForTests();
      let declined = 0;
      for (const turn of TURNS) {
        mockLog.info.mockClear();
        const hash = await serve(turn);
        const plan = mockLog.info.mock.calls.find(
          (c) => c[0] === "followup_fielded"
        )?.[1] as { eligible?: boolean } | undefined;
        if (plan && plan.eligible === false) {
          declined += 1;
          expect(hash, `${mode.name}:${turn.name}`).toBe(
            golden.route[`${mode.name}:${turn.name}`]
          );
        }
      }
      expect(declined, mode.name).toBeGreaterThanOrEqual(3);
    }
  }, 120_000);
});
